+package com.example.contact;
+
+import com.microsoft.playwright.Locator;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/";
+    }
+
+    @Override
+    public String getView() {
+        return "contact";
+    }
+
+    private Locator openDialog() {
+        return page.locator("vaadin-dialog-overlay[opened]");
+    }
+
+    @Test
+    void fullSendFlowInBrowser() {
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+
+        assertTrue(send.isVisible());
+
+        int before = GridElement.get(page).getTotalRowCount();
+
+        send.click();
+        name.assertInvalid();
+        name.assertErrorMessage("Name is required");
+        email.assertInvalid();
+        email.assertErrorMessage("Give an e-mail address or a phone number");
+        message.assertInvalid();
+        message.assertErrorMessage("Message is required");
+
+        name.setValue("Grace Browser");
+        email.setValue("grace@example.com");
+        message.setValue("Hello from a real browser");
+
+        send.click();
+
+        NotificationElement notification = NotificationElement.getByText(page, "Message sent");
+        notification.assertOpen();
+
+        name.assertValue("");
+        email.assertValue("");
+        message.assertValue("");
+
+        GridElement grid = GridElement.get(page);
+        assertEquals(before + 1, grid.getTotalRowCount());
+
+        ButtonElement.getByText(page, "Send").assertDisabled();
+
+        name.setValue("Someone else");
+        ButtonElement.getByText(page, "Send").assertEnabled();
+    }
+
+    @Test
+    void keepEditingStaysOnContactWithInputIntact() {
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.setValue("Not sent yet");
+
+        page.locator("a[router-link]").click();
+
+        Locator dialog = openDialog();
+        assertThat(dialog).isVisible();
+
+        page.getByText("Keep editing").click();
+        assertThat(dialog).not().isAttached();
+
+        name.assertValue("Not sent yet");
+        assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/contact$"));
+    }
+
+    @Test
+    void discardNavigatesToAbout() {
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.setValue("Not sent yet");
+
+        page.locator("a[router-link]").click();
+
+        Locator dialog = openDialog();
+        assertThat(dialog).isVisible();
+        page.getByText("Discard").click();
+
+        assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/about$"));
+    }
+
+    @Test
+    void emptyFormNavigatesWithoutDialog() {
+        page.locator("a[router-link]").click();
+        assertThat(page).hasURL(java.util.regex.Pattern.compile(".*/about$"));
+        assertThat(openDialog()).not().isAttached();
+    }
+}
