+package com.example.contact;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField nameField(ContactView view) {
+        return find(TextField.class).from(view).withLabel("Name").single();
+    }
+
+    private EmailField emailField(ContactView view) {
+        return find(EmailField.class).from(view).withLabel("Email").single();
+    }
+
+    private TextField phoneField(ContactView view) {
+        return find(TextField.class).from(view).withLabel("Phone").single();
+    }
+
+    private TextArea messageField(ContactView view) {
+        return find(TextArea.class).from(view).withLabel("Message").single();
+    }
+
+    private Button sendButton(ContactView view) {
+        return find(Button.class).from(view).withText("Send").single();
+    }
+
+    @Test
+    void headingLinkAndFormArePresent() {
+        ContactView view = navigate(ContactView.class);
+
+        assertTrue(find(com.vaadin.flow.component.html.H1.class).from(view).withText("Contact").exists());
+        RouterLink link = find(RouterLink.class).from(view).withText("About").single();
+        assertEquals(AboutView.class, test(link).getRoute().orElse(null));
+
+        assertEquals("", nameField(view).getValue());
+        assertEquals("", emailField(view).getValue());
+        assertEquals("", phoneField(view).getValue());
+        assertEquals("", messageField(view).getValue());
+        assertTrue(sendButton(view).isEnabled());
+    }
+
+    @Test
+    void aboutViewHasHeading() {
+        AboutView view = navigate(AboutView.class);
+        assertTrue(find(com.vaadin.flow.component.html.H1.class).from(view).withText("About").exists());
+    }
+
+    @Test
+    void blankFormIsInvalid() {
+        ContactView view = navigate(ContactView.class);
+        int before = find(Grid.class).from(view).single().getListDataView().getItemCount();
+
+        test(sendButton(view)).click();
+
+        TextField name = nameField(view);
+        EmailField email = emailField(view);
+        TextArea message = messageField(view);
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertTrue(sendButton(view).isEnabled());
+        assertEquals(before, find(Grid.class).from(view).single().getListDataView().getItemCount());
+    }
+
+    @Test
+    void invalidEmailFormatIsRejected() {
+        ContactView view = navigate(ContactView.class);
+
+        test(nameField(view)).setValue("Ann");
+        test(emailField(view)).setValue("not-an-email");
+        test(messageField(view)).setValue("Hello there");
+
+        test(sendButton(view)).click();
+
+        EmailField email = emailField(view);
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void messageTooLongIsRejected() {
+        ContactView view = navigate(ContactView.class);
+
+        test(nameField(view)).setValue("Ann");
+        test(phoneField(view)).setValue("12345");
+        test(messageField(view)).setValue("a".repeat(501));
+
+        test(sendButton(view)).click();
+
+        TextArea message = messageField(view);
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneIsEnoughToSend() {
+        ContactView view = navigate(ContactView.class);
+        int before = find(Grid.class).from(view).single().getListDataView().getItemCount();
+
+        test(nameField(view)).setValue("Ann Phone");
+        test(phoneField(view)).setValue("555-1234");
+        test(messageField(view)).setValue("Hi, call me");
+
+        test(sendButton(view)).click();
+
+        Notification notification = find(Notification.class).first();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertEquals("", nameField(view).getValue());
+        assertEquals("", emailField(view).getValue());
+        assertEquals("", phoneField(view).getValue());
+        assertEquals("", messageField(view).getValue());
+
+        assertFalse(sendButton(view).isEnabled());
+
+        Grid<ContactMessage> grid = find(Grid.class).from(view).single();
+        assertEquals(before + 1, grid.getListDataView().getItemCount());
+        ContactMessage first = grid.getListDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Ann Phone", first.name());
+    }
+
+    @Test
+    void sendDisabledAfterSendReEnabledOnEdit() {
+        ContactView view = navigate(ContactView.class);
+
+        test(nameField(view)).setValue("Bob");
+        test(emailField(view)).setValue("bob@example.com");
+        test(messageField(view)).setValue("Hello");
+
+        test(sendButton(view)).click();
+        assertFalse(sendButton(view).isEnabled());
+
+        test(nameField(view)).setValue("Carl");
+        assertTrue(sendButton(view).isEnabled());
+    }
+
+    @Test
+    void enterKeySendsForm() {
+        ContactView view = navigate(ContactView.class);
+
+        test(nameField(view)).setValue("Dana");
+        test(emailField(view)).setValue("dana@example.com");
+        test(messageField(view)).setValue("Hi via enter");
+
+        fireShortcut(Key.ENTER);
+
+        assertFalse(sendButton(view).isEnabled());
+        Grid<ContactMessage> grid = find(Grid.class).from(view).single();
+        assertTrue(grid.getListDataView().getItems().anyMatch(m -> "Dana".equals(m.name())));
+    }
+
+    @Test
+    void newestMessageIsFirst() {
+        ContactView view = navigate(ContactView.class);
+
+        test(nameField(view)).setValue("First");
+        test(phoneField(view)).setValue("111");
+        test(messageField(view)).setValue("first message");
+        test(sendButton(view)).click();
+
+        test(nameField(view)).setValue("Second");
+        test(phoneField(view)).setValue("222");
+        test(messageField(view)).setValue("second message");
+        test(sendButton(view)).click();
+
+        Grid<ContactMessage> grid = find(Grid.class).from(view).single();
+        assertEquals("Second", grid.getListDataView().getItems().findFirst().orElseThrow().name());
+    }
+
+    @Test
+    void navigatingAwayWithContentShowsDialog() {
+        ContactView view = navigate(ContactView.class);
+
+        test(nameField(view)).setValue("Not sent yet");
+
+        RouterLink link = find(RouterLink.class).from(view).withText("About").single();
+        test(link).click();
+
+        // Navigation should be postponed: still on contact view.
+        assertTrue(find(com.vaadin.flow.component.html.H1.class).from(view).withText("Contact").exists());
+        Dialog dialog = find(Dialog.class).first();
+        assertTrue(dialog.isOpened());
+
+        Button keepEditing = find(Button.class).from(dialog).withText("Keep editing").single();
+        test(keepEditing).click();
+
+        assertEquals("Not sent yet", nameField(view).getValue());
+
+        // Navigating away must still be interceptable after a prior "Keep editing".
+        test(link).click();
+        Dialog secondDialog = find(Dialog.class).first();
+        assertTrue(secondDialog.isOpened());
+
+        Button discard = find(Button.class).from(secondDialog).withText("Discard").single();
+        test(discard).click();
+
+        assertTrue(find(com.vaadin.flow.component.html.H1.class).withText("About").exists());
+    }
+
+    @Test
+    void discardingNavigatesAway() {
+        ContactView view = navigate(ContactView.class);
+
+        test(nameField(view)).setValue("Not sent yet");
+
+        RouterLink link = find(RouterLink.class).from(view).withText("About").single();
+        test(link).click();
+
+        Dialog dialog = find(Dialog.class).first();
+        Button discard = find(Button.class).from(dialog).withText("Discard").single();
+        test(discard).click();
+
+        assertTrue(find(com.vaadin.flow.component.html.H1.class).withText("About").exists());
+    }
+
+    @Test
+    void emptyFormNavigatesAwayWithoutDialog() {
+        ContactView view = navigate(ContactView.class);
+
+        RouterLink link = find(RouterLink.class).from(view).withText("About").single();
+        test(link).click();
+
+        assertFalse(find(Dialog.class).exists());
+        assertTrue(find(com.vaadin.flow.component.html.H1.class).withText("About").exists());
+    }
+}
